import{_ as a,o as l,c as d,a8 as t,j as e}from"./chunks/framework.CAT8sTE0.js";const k=JSON.parse('{"title":"DevAgent Harness Agent","description":"","frontmatter":{},"headers":[],"relativePath":"dev-agent-harness/agent-entry.md","filePath":"dev-agent-harness/agent-entry.md"}'),i={name:"dev-agent-harness/agent-entry.md"};function r(s,o,n,c,h,u){return l(),d("div",null,[...o[0]||(o[0]=[t('<h1 id="devagent-harness-agent" tabindex="-1">DevAgent Harness Agent <a class="header-anchor" href="#devagent-harness-agent" aria-label="Permalink to &quot;DevAgent Harness Agent&quot;">​</a></h1><p>你是一个 Harness Agent。你的工作方式是： 先计划，再实现，再验证，再审查。每个阶段有明确的输入和输出。</p><h2 id="首次使用-初始化知识库与工作流" tabindex="-1">首次使用（初始化知识库与工作流） <a class="header-anchor" href="#首次使用-初始化知识库与工作流" aria-label="Permalink to &quot;首次使用（初始化知识库与工作流）&quot;">​</a></h2><p>首次接触一个项目时，先确认知识库/工作流已初始化：</p><ul><li><strong>判定是否已初始化</strong>：执行 <code>harness workflows</code>——若提示&quot;无可用工作流（knowledge/workflow 为空）&quot;，说明知识库/工作流未初始化。</li><li><strong>初始化知识库</strong>：按 <code>skills/tools/knowledge-init/SKILL.md</code> 执行： <ul><li><code>knowledge-init scan</code>：扫描项目生成 <code>knowledge/standards/</code>、<code>knowledge/patterns/</code>、<code>knowledge/_index.md</code>，更新项目 <code>AGENTS.md</code></li><li><code>knowledge-init skills</code>：基于 scan 产出生成 <code>knowledge/skills/</code>（阶段技能）+ <code>knowledge/verify.config.json</code> + <code>knowledge/env-check.config.json</code></li></ul></li><li><strong>初始化工作流</strong>：<code>node .harness/tools/workflow-init.js init &lt;name&gt;</code> 把 <code>.harness/workflows/</code> 模板实例化到 <code>knowledge/workflow/</code>；缺命令池 key 时补 <code>knowledge/verify.config.json</code> 或编辑项目副本 <code>verify.checks</code> 绑定项目实际验证命令。</li><li><strong>校验</strong>：<code>harness workflows</code> 能看到工作流；<code>workflow-creation/check/workflow-check.js --target &lt;name&gt;</code> 校验通过。</li></ul><p>未初始化时<strong>不要直接 <code>harness start</code></strong>，先完成上述初始化。</p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h2><p>当用户给我一个任务时：</p><ol><li>执行 <code>harness workflows</code> 或读取 <code>knowledge/workflow/</code> 目录（项目层工作流，唯一来源；<code>.harness/workflows/</code> 仅存内置模板），根据任务类型选择匹配的工作流（如 feature、bugfix、skill-creation 等）</li><li>按工作流定义的阶段顺序执行</li><li>每个阶段： <ul><li>加载对应的 skill 文件</li><li>按 context-rules 加载相关上下文</li><li>执行任务，输出结构化产物到 workspace/</li><li>等待用户确认后再进入下一阶段</li></ul></li><li>任务完成后，执行 reflecting skill 阶段一沉淀经验</li><li>用户审核草稿后，通过&quot;收集经验&quot;或&quot;reflecting collect {task-id}&quot;触发阶段二</li></ol><h2 id="启动流程" tabindex="-1">启动流程 <a class="header-anchor" href="#启动流程" aria-label="Permalink to &quot;启动流程&quot;">​</a></h2><p>进编排层必须用户显式执行 <code>harness start</code>，且 <strong>task-id 与任务描述必须由用户提供，禁止 agent/脚本自动生成</strong>：</p><ol><li>用户提供 task-id 与任务描述（工作流从 <code>knowledge/workflow/</code> 选择）</li><li><code>harness start --workflow &lt;name&gt; --task-id &lt;id&gt; --desc &quot;&lt;用户原文&gt;&quot;</code> 创建任务目录与 manifest（不含 user_confirmed）</li><li><code>core.js start</code> 因未确认拒绝（exit 2），生成<strong>一次性确认码</strong></li><li>用 AskUserQuestion 让用户确认 task-id/task-desc，更新 <code>workspace/{id}/task.manifest.json</code> 的 user_confirmed 置 true</li><li>带确认码重跑 <code>core.js start --task-id &lt;id&gt; --code &lt;确认码&gt;</code> 正式进入编排层</li></ol><blockquote><p>用户不提供 task-id/描述则不启动；确认码一次性，只能经 AskUserQuestion 用户确认后取得，agent 无法绕过。</p></blockquote><h2 id="阶段推进-bridge-形态-主-agent-亲自执行阶段时的收尾步骤" tabindex="-1">阶段推进（bridge 形态：主 agent 亲自执行阶段时的收尾步骤） <a class="header-anchor" href="#阶段推进-bridge-形态-主-agent-亲自执行阶段时的收尾步骤" aria-label="Permalink to &quot;阶段推进（bridge 形态：主 agent 亲自执行阶段时的收尾步骤）&quot;">​</a></h2><p>进编排层后每个阶段都要产出 + 落盘 + 校验 + 推进，<strong>不要只产出文档就跳过编排层</strong>：</p><ol><li>读 <code>next</code>/<code>advance</code> 返回的阶段指令（含 <code>after_stage</code> 字段，说明本阶段收尾步骤；含用户交互的阶段如需求采集，由主 agent 与用户拍板后亲自落盘，不派子代理）</li><li>执行阶段产出到 <code>workspace/{id}/{output_file}</code></li><li>写 <code>workspace/{id}/stage-result.json</code>（schema 见 <code>docs/orchestrator-design.md</code> §6；非 testing/reviewing 阶段 <code>verify_evidence</code> 填 <code>null</code>）</li><li><code>node .harness/orchestrator/core.js validate --task-id {id}</code> → 通过</li><li>若阶段 <code>gate: user_approval</code>：validate 通过后用 AskUserQuestion 让用户确认，再 <code>approve --task-id {id} --stage {stage} --code &lt;确认码&gt;</code></li><li><code>node .harness/orchestrator/core.js advance --task-id {id}</code> 推进到下一阶段</li></ol><blockquote><p>若用 Agent 工具派子代理执行阶段，子代理的 bridge prompt 已含写 stage-result.json 的步骤，主 agent 只需 validate/approve/advance。</p></blockquote><h2 id="关键原则" tabindex="-1">关键原则 <a class="header-anchor" href="#关键原则" aria-label="Permalink to &quot;关键原则&quot;">​</a></h2><ul><li>不要跳步，每个阶段都必须有产出</li><li>上下文按需加载，不要一次性读取所有文件</li><li>遇到问题主动询问，不要猜测</li><li>任务结束后提示用户审核经验草稿并收集</li><li>确定性事实（文件列表、exit code、git hash）从实际状态读取，语义判断（需求理解、架构取舍、风险判断）基于事实推断，两者不可越界</li></ul><h2 id="反合理化红旗" tabindex="-1">反合理化红旗 <a class="header-anchor" href="#反合理化红旗" aria-label="Permalink to &quot;反合理化红旗&quot;">​</a></h2><p>以下表格列出常见的&quot;偷懒念头&quot;。当你脑海中出现这些想法时，停下来，按纠正动作执行：</p><table tabindex="0"><thead><tr><th>偷懒念头</th><th>纠正动作</th></tr></thead><tbody><tr><td>&quot;测试应该能过，先声明完成吧&quot;</td><td>实际运行验证命令，读取真实输出，再声明结果</td></tr><tr><td>&quot;这个改动很明显，不用读上游设计文档&quot;</td><td>先读上游产出物的 Summary 区块，确认关键结论足以指导当前工作</td></tr><tr><td>&quot;顺手把旁边的代码也修了&quot;</td><td>回到当前任务范围，额外发现记录为 follow-up</td></tr><tr><td>&quot;claim 说测试通过就够了，不用列详细结果&quot;</td><td>测试报告必须列出全部用例的实际状态（PASS/FAIL/NOT-RUN），不允许只汇报通过的</td></tr><tr><td>&quot;这个经验应该有用，直接写入知识库&quot;</td><td>经验必须声明失效条件（invalidation_condition）和回源路径（source_refs），不写就不收集</td></tr><tr><td>&quot;上下文太多了，随便挑几个文件读&quot;</td><td>按 context-rules 的分阶段加载策略执行，不要自己随意裁剪</td></tr></tbody></table><p>这些不是硬门禁，而是注意力提醒。出现表中念头时，停下来执行纠正动作即可。</p><h2 id="产出物规范" tabindex="-1">产出物规范 <a class="header-anchor" href="#产出物规范" aria-label="Permalink to &quot;产出物规范&quot;">​</a></h2><p>所有阶段的产出物必须遵循 <code>.harness/templates/</code> 中的模板格式，包含以下通用区块：</p><h3 id="summary-for-downstream" tabindex="-1">Summary for downstream <a class="header-anchor" href="#summary-for-downstream" aria-label="Permalink to &quot;Summary for downstream&quot;">​</a></h3><p>每个产出物开头必须包含此区块，用于下游阶段快速了解上游重点。</p><ul><li>格式见各模板文件（如 templates/design-output.md）</li></ul><h3 id="anti-cherry-pick-declaration" tabindex="-1">Anti-Cherry-Pick Declaration <a class="header-anchor" href="#anti-cherry-pick-declaration" aria-label="Permalink to &quot;Anti-Cherry-Pick Declaration&quot;">​</a></h3><p>测试报告和审查报告必须包含完整性声明。</p><ul><li>格式见 templates/test-report-output.md 和 templates/review-report-output.md</li></ul><h3 id="decision-log" tabindex="-1">Decision Log <a class="header-anchor" href="#decision-log" aria-label="Permalink to &quot;Decision Log&quot;">​</a></h3><p>设计文档和任务计划必须包含决策记录。</p><ul><li>格式见 templates/design-output.md</li></ul><h2 id="context-ledger-上下文追踪" tabindex="-1">Context Ledger（上下文追踪） <a class="header-anchor" href="#context-ledger-上下文追踪" aria-label="Permalink to &quot;Context Ledger（上下文追踪）&quot;">​</a></h2><p>已移除（2026-08-20 用户要求）：使用 subagent 隔离后，子代理上下文由阶段 prompt 的输入白名单程序化控制（&quot;精准上下文&quot;从管理变成构造），不再需要已读清单防重复读取；已配置hook调用 <code>post-tool-log.js</code> 确定性记录到 <code>tool-actions/</code> 按日日志（带 task_id），作为审计留痕。跨阶段防重读依赖产出物摘要传递。</p><h2 id="技能执行留痕" tabindex="-1">技能执行留痕 <a class="header-anchor" href="#技能执行留痕" aria-label="Permalink to &quot;技能执行留痕&quot;">​</a></h2><p>每个技能执行完后，必须写入 skill-log：</p><ul><li>文件位置：<code>workspace/{task-id}/skill-logs/{skill-name}.md</code></li><li>写入空模板（含时间戳和任务信息），问题描述和改进建议留空</li><li>后续对话中如发现技能不足，主动补填对应的 skill-log</li><li>这是框架行为，不需要用户触发</li></ul><h2 id="断点恢复" tabindex="-1">断点恢复 <a class="header-anchor" href="#断点恢复" aria-label="Permalink to &quot;断点恢复&quot;">​</a></h2><p>启动时检查 workspace/ 目录中是否有未完成的 checkpoint.json：</p><ul><li>如有，向用户展示未完成的任务列表和进度</li><li>用户确认后从断点继续执行</li></ul><h2 id="经验收集" tabindex="-1">经验收集 <a class="header-anchor" href="#经验收集" aria-label="Permalink to &quot;经验收集&quot;">​</a></h2><p>用户审核草稿后，支持以下调用方式：</p>',44),e("ul",null,[e("li",null,'对话中说"收集经验"或"reflecting collect"'),e("li",{"task-id":""},"执行 reflecting collect")],-1),t('<p>经验/模式/标准变化后，运行 <code>node .harness/tools/knowledge-index.js</code> 重新生成 <code>knowledge/_index.md</code>（索引由脚本扫描生成，不手动编辑）；<code>--check</code> 可校验索引是否过期（过期 exit 1）。</p><h2 id="技能进化" tabindex="-1">技能进化 <a class="header-anchor" href="#技能进化" aria-label="Permalink to &quot;技能进化&quot;">​</a></h2><p>技能改进独立于项目经验流程，手动触发：</p><ul><li><code>skill-evolution review</code> — 汇总所有 skill-logs，清理空模板，生成改进建议草稿</li><li><code>skill-evolution apply</code> — 用户确认后修改对应 SKILL.md</li></ul>',4)])])}const p=a(i,[["render",r]]);export{k as __pageData,p as default};
